INSERT INTO feature VALUES('inert-fields','modules','A theory''s inert operations and inert definitions','packages','implemented','ordinary',NULL,'A theory''s operation marked `@[ inert ]` is a field the manifest step reads, a package''s name or version: a model''s component for it is inert, and an `include` carries the mark. A top-level definition marked `@[ inert ]` is inert too, so a map or a render over inert fields has a declaration to live in; a module''s member takes no mark. A declaration that is not inert and reads an inert one, by its path, by its name inside the model or off a model binder, is refused `InertRead` by the inert declaration''s name; a sort takes no mark, and a theory''s member takes no other attribute. A package''s address leaves every inert declaration out, so an edit to one moves no address.','surface-grammar surface-lowering surface-dispatcher','corpus/model/modules/inert-field.gandr corpus/pathological/modules/inert-field.gandr corpus/ledger/attributes/inert.gandr crates/surface-lowering/tests/modules/models.rs::an_inert_field_is_read_only_by_another_3029 crates/surface-lowering/tests/modules/models.rs::an_inert_definition_is_read_only_by_an_inert_reader_6141 crates/surface-dispatcher/tests/package.rs::every_corpus_package_s_address_ignores_its_inert_fields_3030 crates/surface-dispatcher/tests/package.rs::an_edit_to_an_inert_definition_leaves_the_address_6141','corpus/ledger/features/inert-fields.gandr',NULL);
